import katex from "katex";
import "katex/contrib/mhchem";

import { sanitizeRichText } from "./sanitize";

/**
 * Rich text → HTML for the browser.
 *
 * Two steps, and the order is the whole point:
 *
 *   1. `sanitizeRichText` decides what markup is allowed to exist.
 *   2. Math is rendered *after* that, because KaTeX emits `<span style="…">`
 *      and the sanitizer strips every style attribute. Rendering first would
 *      have the layout thrown away; rendering second keeps it, and KaTeX's
 *      output is generated by us rather than by the author, so it does not
 *      need to pass the allowlist.
 *
 * The stored form of a formula is the LaTeX source on a math node
 * (`<span data-type="inline-math" data-latex="x^2"></span>`), never KaTeX's
 * rendered DOM — that would bloat every row and freeze our KaTeX version into
 * the database.
 */

const INLINE_MATH_PATTERN =
  /<span data-type="inline-math" data-latex="([^"]*)"(?: data-science-template="[^"]*" data-science-values="[^"]*")?><\/span>/g;
const BLOCK_MATH_PATTERN = /<div data-type="block-math" data-latex="([^"]*)"><\/div>/g;

/** Undo the escaping `sanitizeRichText` applied to the attribute value. */
function decodeAttributeValue(value: string): string {
  return value
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

function escapeHtml(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function renderMath(latex: string, displayMode: boolean): string {
  const source = decodeAttributeValue(latex);
  try {
    return katex.renderToString(source, {
      displayMode,
      throwOnError: false,
      strict: false,
      // `trust` stays false: it is what stops \href / \url from becoming a link
      // to an arbitrary URL inside a question body.
      trust: false,
      maxSize: 20,
      maxExpand: 1000,
      // Keep MathML for screen readers; the visual HTML twin is aria-hidden by KaTeX.
      output: "htmlAndMathml",
    });
  } catch {
    return `<code class="text-danger">${escapeHtml(source)}</code>`;
  }
}

/**
 * Sanitised, math-rendered HTML ready for `dangerouslySetInnerHTML`.
 * Safe to call during render — it is pure and synchronous.
 */
export function renderRichText(html: string): string {
  if (!html) return "";
  const clean = sanitizeRichText(html);
  return clean
    .replace(INLINE_MATH_PATTERN, (_match, latex: string) => renderMath(latex, false))
    .replace(BLOCK_MATH_PATTERN, (_match, latex: string) => renderMath(latex, true));
}
